
const q=new URLSearchParams(location.search);
// Ship only the selected direction; historical variant renderers are inactive.
if(q.has('board')&&!['journey','approved'].includes(q.get('board')))q.delete('board');
let direction='A',screen=q.get('screen')||'select',current=0,cover=0,modal='',toast='',profile='Instagram',look='Original',textDraft='',posDraft='center',note='',galleryFilter='All',kriaDraft='',kriaRequest='',kriaProposal=null,kriaApplied=false,kriaBefore=null,kriaHelp='',timer;let chosen=new Set([0,1,2,3,4,5]),order=[0,1,2,3,4,5],caption='Little streets, long afternoons, and nowhere else to be. A few summer moments worth keeping.';
const media=[{img:'corfu.jpg',name:'The first glimpse',role:'Opening',text:'A slower\nkind of\nsummer.',position:'top'},{img:'trulli-street.jpg',name:'Take the long way',role:'A little detail',text:'No rush.\nNo wrong turns.'},{img:'alberobello.jpg',name:'Let the day unfold',role:'A change of pace',video:'0:12',text:''},{img:'lisbon.jpg',name:'A city, unhurried',role:'A new perspective',text:''},{img:'istanbul.jpg',name:'Stay a little longer',role:'A moment in motion',video:'0:08',text:''},{img:'corfu.jpg',name:'Back to the sea',role:'Closing',text:'More days\nlike this.'}];
const names={A:'Preview-first',B:'Storyboard-first',C:'Conversation-first'},steps=[['select','Select media'],['composing','AI composition'],['review','Review post'],['arrange','Arrange slides'],['text','Edit text'],['style','Choose style'],['caption','Post caption'],['export','Export'],['recovery','Recovery'],['gallery','Gallery']];
const paths={sparkles:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z"/><path d="m20 2 .8 2.2L23 5l-2.2.8L20 8l-.8-2.2L17 5l2.2-.8Z"/>',back:'<path d="m14 5-7 7 7 7"/>',next:'<path d="m10 5 7 7-7 7"/>',menu:'<path d="M5 8h14M5 15h10"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',down:'<path d="m6 9 6 6 6-6"/>',up:'<path d="m6 15 6-6 6 6"/>',play:'<path d="m9 5 10 7-10 7Z"/>',layers:'<rect x="4" y="7" width="13" height="13" rx="2"/><path d="M8 3h10a3 3 0 0 1 3 3v10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',text:'<path d="M4 6h16M12 6v15M8 21h8M4 6v3M20 6v3"/>',style:'<circle cx="12" cy="12" r="9"/><path d="M12 3a9 9 0 0 0 0 18Z"/>',caption:'<path d="M6 5h12a3 3 0 0 1 3 3v7a3 3 0 0 1-3 3h-6l-5 3v-3H6a3 3 0 0 1-3-3V8a3 3 0 0 1 3-3Z"/><path d="M7 10h10M7 14h7"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v13h5"/>',share:'<path d="M12 15V3m-4 4 4-4 4 4M6 10H4v11h16V10h-2"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',edit:'<path d="m4 16 11-11 4 4L8 20H4Zm9-9 4 4"/>',retry:'<path d="M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 14-1l1 6M4 12l1 6a8 8 0 0 0 14-1"/>',send:'<path d="M12 20V4m-6 6 6-6 6 6"/>',signal:'<path d="M3 17v3M8 13v7M13 8v12M18 3v17"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M6 12a10 10 0 0 1 12 0M10 16a3 3 0 0 1 4 0"/><circle cx="12" cy="20" r=".5"/>',battery:'<rect x="2" y="6" width="17" height="12" rx="3"/><path d="M22 10v4M5 9h10v6H5Z"/>',trash:'<path d="M4 6h16M9 3h6M6 6l1 15h10l1-15M10 10v7M14 10v7"/>'};
const ic=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.layers}</svg>`,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),img=i=>`<img src="../../../../src/apps/web/public/landing/raw-story/${media[i].img}" alt="${media[i].name}" draggable="false">`;
function btn(label,a,icon='',cls='quiet',extra=''){return `<button class="${cls}" data-do="${a}" ${extra}>${icon?ic(icon):''}${label}</button>`}function ib(n,label,a,cls=''){return btn('',a,n,'iconbtn '+cls,`aria-label="${label}"`)}
function head(title='Summer moments',back=false){return `<div class="status"><span>9:41</span><div class="island"></div><span class="statusicons">${ic('signal')}${ic('wifi')}${ic('battery')}</span></div><header class="apphead">${ib(back?'back':'menu',back?'Back to post':'Open projects',back?'review':'drawer',back?'':'menu')}<span class="title">${title}</span>${ib('more','Post options','options')}</header>`}function foot(label,a,extra=''){return `<footer class="appfoot">${extra}${btn(label,a,'','primary')}</footer>`}function body(x,cls=''){return `<div class="appbody ${cls}">${x}</div>`}
function canvas(i=current,editing=false){let m=media[i],t=editing?textDraft:m.text,p=editing?posDraft:m.position||'center',treatment=screen==='style'?look:m.look||'Original',effect=({'Olive Film':'olive','Smoky Split-Tone':'smoky','Golden Hour':'golden','Faded Analog':'faded'})[treatment]||'';return `<div class="canvas ${effect} ${profile==='TikTok'?'tiktok':''}">${img(i)}${t?`<div class="canvastext ${p}">${esc(t)}</div>`:''}<span class="canvaslabel">${i===cover?'Cover':m.video?'Video':'Photo'}</span>${m.video?ib('play','Play this slide','play','playbutton'):''}</div>`}function rail(){return `<div class="rail" aria-label="Slide navigation">${order.map((id,j)=>btn(img(id)+`<span>${j+1}${media[id].video?' ▷':''}</span>`,'slide:'+id,'','thumb '+(id===current?'active':''),`aria-label="Slide ${j+1}: ${media[id].name}" aria-current="${id===current}"`)).join('')}</div>`}function tools(){return `<div class="tools">${[['grid','Arrange','arrange'],['text','Text','text'],['style','Style','style'],['caption','Caption','caption']].map(([i,t,a])=>btn(t,a,i,'tool')).join('')}</div>`}function receipt(){return `<div class="receipt"><span>${profile} · ${profile==='TikTok'?'9:16':'4:5'}</span><span class="saved">${ic('check')}Draft saved</span></div>`}function pager(){return `<div class="pager"><span>${order.indexOf(current)+1} of ${order.length}</span>${btn(current===cover?'Cover slide':'Make cover','cover')}</div>`}
function select(){return head()+body(`<h2>Your moments.<br>One good story.</h2><div class="meta"><span class="chip">${ic('layers')}Slide post</span>${btn(profile,'platform','down')}</div><div class="selectgrid">${media.map((m,i)=>btn(img(i)+`<span class="tick">${chosen.has(i)?ic('check'):''}</span>${m.video?`<span class="duration">${ic('play')}${m.video}</span>`:''}`,'toggle:'+i,'','tile '+(chosen.has(i)?'selected':''),`aria-label="${chosen.has(i)?'Deselect':'Select'} ${m.name}" aria-pressed="${chosen.has(i)}"`)).join('')}</div><div class="meta"><span class="small">${chosen.size} selected</span>${btn('Add media','add','plus')}</div><label class="fieldlabel" for="direction">Tell Kria <span>Optional</span></label><textarea id="direction" placeholder="Keep it warm, candid, and unhurried.">${esc(note)}</textarea>`)+foot('Compose post','compose')}
function loading(prep=false){return head()+body(`<div class="loadingart">${img(1)}${img(3)}${img(0)}</div><h2>${prep?'Getting your post<br>ready.':'Finding the thread<br>in your moments.'}</h2><p class="sub" style="margin-top:12px">${prep?'Preparing the photos and videos in your chosen order.':'A beginning, the little details, and a moment to end on.'}</p><div class="statusline"><span class="spinner"></span><div>${prep?'Preparing slide files…':'Composing your post…'}<p class="small">${prep?'Your edits are saved.':'Your original media stays unchanged.'}</p></div></div><p class="small">You can return to this post from your chat.</p>`)+foot('Back to chat','chat')}
function reviewA(){return head('Post preview',true)+body(receipt()+`<div class="previewwrap"><div class="stage">${canvas()}</div>${ib('sparkles','Open Kria conversation','kria','kria-fab')}</div>`+pager()+rail()+tools())+foot('Prepare post','prepare','<p class="small">Review the draft before exporting</p>')}
function rows(reorder=false){return order.map((id,j)=>`<div class="row">${img(id)}<div class="text"><div class="role">${String(j+1).padStart(2,'0')} / ${media[id].role}</div><div class="name">${media[id].name}</div>${id===cover?'<span class="cover">Cover</span>':!reorder?`<p class="small">${media[id].video?'Video · '+media[id].video:'Photo'}</p>`:''}</div><div class="rowactions">${reorder?ib('up',`Move slide ${j+1} earlier`,'earlier:'+id)+ib('down',`Move slide ${j+1} later`,'later:'+id):ib('edit','Edit '+media[id].name,'edit:'+id)}</div></div>`).join('')}
function reviewB(){return head('Your story',true)+body(receipt()+'<h2>A little summer,<br>in six moments.</h2><div class="narrative">A quiet opening, small discoveries, then back to the sea.</div>'+rows())+`<div style="padding:0 20px">${tools()}</div>`+foot('Prepare post','prepare')}
function chat(){return head()+body(`<div class="meta" style="margin-top:0"><span class="chip">${ic('layers')}Slide post</span><span class="small">${order.length} slides</span></div><h2>Here’s your first draft.</h2><p class="chatcopy">I’d open by the water, linger on the little details, then come back to the sea.</p><div class="chatstage">${canvas()}</div><div class="pager"><span>${order.indexOf(current)+1} of ${order.length}</span>${btn('Edit slides','editor','edit')}</div>${rail()}`)+`<footer class="appfoot">${btn('Prepare post','prepare','','primary')}<div class="composer"><input aria-label="Message to Kria" placeholder="Tell Kria what to change"><button data-do="send" aria-label="Send message">${ic('send')}</button></div></footer>`}
function arrange(){return head('Arrange slides',true)+body('<h2>Every slide has a place.</h2><p class="sub" style="margin:9px 0 14px">Change the order to shape your story.</p><div class="reorder">'+rows(true)+'</div>'+btn('Add photos & videos','add','plus','secondary')+'<p class="small" style="margin-top:14px">The cover stays with its photo when you move it.</p>')+foot('Done','review')}
function textview(){return head('Slide text',true)+body(`<div class="receipt"><span>Slide ${order.indexOf(current)+1} of ${order.length}</span><span>Text preview</span></div><div class="editstage" id="edit-preview">${canvas(current,true)}</div><label class="fieldlabel" for="overlay-text">On-screen text</label><textarea id="overlay-text" maxlength="120">${esc(textDraft)}</textarea><div class="counter"><span id="text-count">${textDraft.length}</span> / 120</div><label class="fieldlabel">Position</label><div class="segments">${['top','center','bottom'].map(p=>btn(p[0].toUpperCase()+p.slice(1),'position:'+p,'',p===posDraft?'active':'')).join('')}</div><p class="small">One text block per slide. Clear the text to show only your moment.</p>`)+foot('Save text','savetext')}
function styleview(){return head('Slide style',true)+body(`<div class="receipt"><span>Slide ${order.indexOf(current)+1} of ${order.length}</span><span>Style preview</span></div><div class="stage" style="width:260px">${canvas()}</div><label class="fieldlabel">Look</label><div class="lookrail">${[['Original',''],['Olive Film','olive'],['Smoky Split-Tone','smoky'],['Golden Hour','golden'],['Faded Analog','faded']].map(([n,c])=>btn(img(current)+n,'look:'+n,'','look '+c+(look===n?' active':''),`aria-pressed="${look===n}"`)).join('')}</div><p class="small" style="margin-top:12px">Applies to this slide.</p>`)+foot('Save style','savestyle')}
function captionview(){return head('Post caption',true)+body(`<h2>The words that go<br>with your moments.</h2><div class="mini">${img(cover)}<div>Summer moments<p>${profile} · ${order.length} slides</p></div></div><label class="fieldlabel" for="post-caption">Caption <span>Optional</span></label><textarea id="post-caption" rows="7" maxlength="2200">${esc(caption)}</textarea><div class="counter"><span id="caption-count">${caption.length}</span> / 2,200</div><p class="small" style="margin-top:16px">Copy this caption when you share your post.</p>`)+foot('Save caption','savecaption')}
function exportview(){return head('Your post',true)+body(`<span class="ready">${ic('check')}Ready to export</span><h2>One story.<br>Ready to share.</h2><div class="exportstage">${canvas(cover)}</div><div class="strip">${order.map(img).join('')}</div><div class="meta"><span>${order.length} slides · ${profile}</span><span class="small">Photos${profile==='Instagram'?' & videos':''}</span></div><div class="captionblock"><div class="fieldlabel">Post caption ${btn('Copy','copy','copy')}</div><p>${esc(caption)}</p></div>`)+`<footer class="appfoot exportfoot">${btn('Save '+order.length+' slides','savephotos','download','primary')}${btn('Share files','share','share','secondary')}<p class="small">Upload the slides in order in ${profile}.</p></footer>`}
function recovery(){return head('Your post',true)+body(`<h2>Your draft is here.<br>One slide needs a look.</h2><p class="sub" style="margin-top:12px">The video “Stay a little longer” couldn’t be prepared.</p><div class="mini">${img(4)}<div>Stay a little longer<p>Video · 0:08</p></div>${ib('retry','Retry this slide','retryfailed')}</div><div class="notice"><strong>The complete post isn’t ready yet.</strong>Your order, text, and caption are saved. Retry this slide, or remove it to prepare the rest.</div>${btn('Remove this slide','removefailed','trash','secondary')}<h3 style="margin-top:28px">Still in your post</h3><div class="strip" style="justify-content:flex-start;margin-top:15px">${order.filter(id=>id!==4).map(img).join('')}</div><p class="small">Nothing is exported until you review the complete post.</p>`)+foot('Retry slide','retryfailed')}
function gallery(){return head('Gallery')+body(`<h2>Gallery</h2><p class="sub" style="margin-top:7px">Your finished videos and posts.</p><div class="galleryfilters">${['All','Ready','In progress'].map((n,i)=>btn(n,'filter:'+n,'',n===galleryFilter?'active':'')).join('')}</div><div class="gallerygrid">${galleryFilter==='In progress'?'<p class="sub">No posts in progress.</p>':btn(canvas(cover)+`<div class="name">Summer moments</div><p class="small">Slide post · ${order.length} slides</p><span class="ready" style="margin-top:7px">${ic('check')}Ready</span>`,'export','','gallerycard')}</div>`)+foot('New post','select')}

function kriaSheet(){return `<div class="shade"><section class="sheet kria-sheet" role="dialog" aria-modal="true" aria-label="Kria editing conversation"><div class="grab"></div><div class="sheethead"><div><h3>Kria</h3><p class="small">Summer moments · Slide post</p></div>${ib('close','Close Kria conversation','dismiss')}</div><div class="kria-context">${img(current)}<div>Editing your post<p class="small">Slide ${order.indexOf(current)+1} of ${order.length} selected</p></div></div><div class="kria-messages" aria-live="polite">${kriaRequest?`<div class="user-bubble">${esc(kriaRequest)}</div>`:'<p class="kria-copy">What would you like to change?</p>'}${kriaProposal?`<p class="kria-copy">${kriaProposal.type==='text'?'A shorter opening gives your photo more room.':kriaProposal.type==='cover'?'This moment can be the first impression.':'Let’s open with your closing moment.'}</p><div class="ai-proposal"><div class="overline">Suggested change</div>${kriaProposal.type==='text'?`<p class="proposal-before">${esc(media[kriaProposal.target].text)}</p><p class="proposal-after">${esc(kriaProposal.text)}</p>`:`<p class="proposal-after">${kriaProposal.type==='cover'?'Make “'+esc(media[kriaProposal.target].name)+'” the cover.':'Move “'+esc(media[kriaProposal.target].name)+'” to the beginning.'}</p>`}<p class="small">${kriaProposal.type==='text'?'Slide '+(order.indexOf(kriaProposal.target)+1)+' only. Other slides stay as they are.':'Your text, style, and caption stay as they are.'}</p>${btn('Apply change','aiapply','','primary')}${btn('Keep current version','aidiscard','','quiet')}</div>`:kriaApplied?'<p class="kria-copy">Applied. Your updated post is ready to review.</p>'+btn('Undo last change','aiundo','retry','quiet'):kriaHelp?`<p class="kria-copy">${esc(kriaHelp)}</p>`:'<p class="small">Ask about the order, cover, text, or feel of your post.</p>'}</div>${!kriaProposal?`<div class="ai-suggestions">${btn('Shorten this text','aisuggest:text','','suggestion')}${btn('Make this the cover','aisuggest:cover','','suggestion')}</div>`:''}<form class="kria-composer"><textarea id="kria-message" rows="1" aria-label="Tell Kria what to change" placeholder="Tell Kria what to change…">${esc(kriaDraft)}</textarea>${btn('','aisend','send','ai-send',`aria-label="Send message to Kria" ${!kriaDraft.trim()?'disabled':''}`)}</form></section></div>`}
function proposeKria(){if(!kriaDraft.trim())return;kriaRequest=kriaDraft.trim();kriaDraft='';kriaApplied=false;kriaHelp='';const request=kriaRequest.toLowerCase();if(/cover/.test(request))kriaProposal={type:'cover',target:current};else if(/short|text|opening/.test(request))kriaProposal={type:'text',target:current,text:'Summer, slowly.'};else if(/order|last|beginning|first/.test(request))kriaProposal={type:'order',target:order.at(-1)};else{kriaProposal=null;kriaHelp='This demo includes shortening slide text, changing the cover, and changing the opening slide. Try one of those edits.'}render()}

function sheet(){if(modal==='kria')return kriaSheet();let title='',content='';switch(modal){case'platform':title='Post format';content=['Instagram','TikTok'].map(n=>btn(`<span class="text">${n==='TikTok'?'TikTok photo post':n}<p class="small">${n==='TikTok'?'Photos only · Portrait 9:16':'Photos & videos · Portrait 4:5'}</p></span><span class="radio ${profile===n?'on':''}"></span>`,'platform:'+n,'','option')).join('')+'<p class="small" style="margin-top:17px">Changing format can change how your photos are cropped.</p>';break;case'incompatible':title='TikTok uses photos only';content='<p class="sub">This post includes videos. Keep the mixed-media post on Instagram, or make a separate draft with your photos.</p>'+btn('Keep Instagram','dismiss','','primary')+btn('Start a photo-only draft','photodraft','','secondary');break;case'add':title='Add photos & videos';content=btn('Choose from Photos','sampleadd','grid','secondary')+btn('Choose from Files','sampleadd','plus','secondary')+'<p class="small" style="margin-top:17px">The app opens the native iOS picker. This prototype uses sample media.</p>';break;case'share':title='Share post files';content=`<p class="sub">${order.length} ordered photos and videos, with a caption file.</p>`+btn('Open iOS share sheet','simshare','share','primary')+btn('Share ZIP bundle','simzip','download','secondary')+'<p class="small" style="margin-top:17px">This is an export, not a published post.</p>';break;case'options':title='Post options';content=btn('Open chat','chat','caption','secondary')+btn('View in Gallery','gallery','layers','secondary')+btn('Show recovery state','recovery','retry','secondary');break;case'drawer':title='Your workspace';content=btn('Gallery','gallery','grid','secondary')+btn('Summer moments','chat','caption','secondary')+btn('New chat','select','plus','secondary');break;}return `<div class="shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="grab"></div><div class="sheethead"><h3>${title}</h3>${ib('close','Close sheet','dismiss')}</div>${content}</section></div>`}
function phone(s){const views={select,composing:()=>loading(),preparing:()=>loading(true),review:()=>direction==='B'?reviewB():direction==='C'?chat():reviewA(),chat,arrange,text:textview,style:styleview,caption:captionview,export:exportview,recovery,gallery};return `<div class="phone">${(views[s]||reviewA)()}<div class="homebar"></div>${modal?sheet():''}${toast?`<div class="toast" role="status">${esc(toast)}</div>`:''}</div>`}
const desc={select:['Start with their moments','One mixed-media selection. Optional direction gives Kria context without asking the creator to fill out a brief.'],composing:['Show real work, calmly','No guessed percentages. Keep selections, show a truthful stage, and provide a route back through chat.'],review:['Preview first. Kria one tap away.','The selected direction keeps the native 52-point floating Kria button. Open a contextual chat sheet, request an edit, review the suggestion, then return to the same slide.'],arrange:['Order shapes the story','Preserve cover identity through every move. Pair native drag with explicit accessible move actions.'],text:['One deliberate text block','The existing 120-character contract, with top, center, and bottom placement. Preview typography is illustrative.'],style:['A consistent treatment','Reuse the same five looks as web. These visual samples do not certify preview/export parity.'],caption:['Finish the thought','Keep post-level captions distinct from text placed on a slide. Edit and copy are separate actions.'],export:['Export the actual post','Separate ordered media, plus the caption. The abbreviated MP4 must never masquerade as the finished post.'],recovery:['Keep the work, name the gap','Identify the affected slide. A partial render does not become a silently incomplete export.'],gallery:['Posts belong beside videos','Label posts with their slide count. Open the slide workspace instead of the video timeline.']};
function render(){let board=q.get('board');if(board==='approved'){direction='A';screen='review';const before=media[0].text;const first=phone('review');modal='kria';kriaRequest='Shorten the opening text';kriaProposal={type:'text',target:0,text:'Summer, slowly.'};const second=phone('review');modal='';kriaProposal=null;media[0].text='Summer, slowly.';const third=phone('review');media[0].text=before;kriaRequest='';root.innerHTML=`<main class="board"><header class="boardhead"><div><div class="overline">Kria / KRI-160 / Selected direction</div><h1>A / Preview first, with Kria close by.</h1></div><p>The existing floating AI button stays.<br>Chat edits open in a native sheet, then return to your post.</p></header><div class="boardphones">${[first,second,third].map((html,i)=>`<section class="boardphone"><div class="label">${['01 / Review your post','02 / Ask Kria for an edit','03 / Apply and keep creating'][i]}</div>${html}</section>`).join('')}</div><div class="boardfoot"><span>Option A selected · Floating Kria AI retained</span><span>Interactive design prototype · Sample conversation</span></div></main>`;return}if(board){direction=board==='flow'?'A':board;textDraft=media[current].text;posDraft=media[current].position||'center';let states=board==='flow'?['select','composing','review','arrange','text','export']:['select','review','export'];root.innerHTML=`<main class="board"><header class="boardhead"><div><div class="overline">Kria / KRI-160 / iPhone</div><h1>${board==='flow'?'From moments to a swipeable story':board+' / '+names[direction]}</h1></div><p>Native mobile design proposal.<br>Existing Kria typography, Sunlit colors, and project navigation.</p></header><div class="boardphones">${states.map((s,i)=>`<section class="boardphone"><div class="label">${String(i+1).padStart(2,'0')} / ${steps.find(x=>x[0]===s)?.[1]||s}</div>${phone(s)}</section>`).join('')}</div><div class="boardfoot"><span>Option A selected · Floating Kria AI retained · Sample media</span><span>Photos + videos, exported as separate slides</span></div></main>`;return}let d=desc[screen]||desc.review;root.innerHTML=`<header class="sitehead"><div class="brand"><span class="logotype">kria</span><span class="overline">Slide posts for iPhone</span></div><span class="badge">KRI-160 · Option A selected</span></header><main class="workspace"><aside class="sidebar"><div class="overline">A native mobile flow</div><h1>A post worth<br>swiping.</h1><p class="intro">Your photos and videos,<br>shaped into one connected story.</p><nav class="steps" aria-label="Prototype screens">${steps.map(([s,n],i)=>btn(`<span class="num">${String(i+1).padStart(2,'0')}</span>${n}`,'nav:'+s,'',screen===s?'active':'',`aria-current="${screen===s?'page':'false'}"`)).join('')}</nav><p class="disclaimer">Interactive design prototype.<br>All uploads, progress, and exports are simulated. No real media is sent or saved.</p></aside><section class="phonewrap" aria-label="Mobile prototype">${phone(screen)}</section><aside class="aside"><div><div class="overline">Explore the layout</div><div class="dirs">${['A'].map(x=>btn(x,'direction:'+x,'',x===direction?'active':'',`aria-label="${names[x]}" aria-pressed="${x===direction}"`)).join('')}</div><h3>${direction} / ${names[direction]}</h3><p>${direction==='A'?'Recommended: one large preview and a visible slide order. Focused controls stay within thumb reach.':direction==='B'?'See the narrative as a sequence of scenes. Easier to compare order, with less room to judge each composition.':'Keep the AI conversation in the foreground, with a focused editor one tap away.'}</p>${btn('View this direction','nav:review','next','asidelink')}</div><div><div class="divider"></div><div class="overline">This screen</div><h3>${d[0]}</h3><p>${d[1]}</p><div class="asidenote"><strong>Before implementation</strong>Native slide export and the on-device rendering contract need engineering qualification. These screens propose behavior; they do not certify backend support.</div><a class="asidelink" href="../handoff.md">Read design handoff ${ic('next')}</a></div></aside></main>`;if(modal)setTimeout(()=>document.querySelector('.sheet button')?.focus(),0)}
function go(s){clearTimeout(timer);screen=s;modal='';toast='';if(s==='style')look=media[current].look||'Original';if(s==='text'){textDraft=media[current].text;posDraft=media[current].position||'center'}let u=new URL(location);u.searchParams.set('screen',screen);u.searchParams.set('direction',direction);history.replaceState(null,'',u);render()}function say(s){toast=s;render();setTimeout(()=>{toast='';render()},3000)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-do]');if(!el||q.get('board'))return;const a=el.dataset.do,[op,v]=a.split(':');if(op==='nav'){go(v);return}if(op==='direction'){direction='A';go('review');return}if(op==='slide'){current=+v;render();return}if(op==='toggle'){chosen.has(+v)?chosen.delete(+v):chosen.add(+v);render();return}if(op==='edit'){current=+v;go('text');return}if(op==='earlier'||op==='later'){let j=order.indexOf(+v),k=j+(op==='earlier'?-1:1);if(k>=0&&k<order.length){[order[j],order[k]]=[order[k],order[j]];render()}return}if(op==='position'){posDraft=v;render();return}if(op==='look'){look=v;render();return}if(op==='platform'&&v){if(v==='TikTok'&&order.some(id=>media[id].video)){modal='incompatible';render()}else{profile=v;modal='';render()}return}if(op==='aisuggest'){kriaDraft=v==='text'?'Shorten this text':'Make this the cover';render();document.getElementById('kria-message')?.focus();return}if(op==='filter'){galleryFilter=v;render();return}
switch(a){case'aisend':proposeKria();break;case'aiapply':if(kriaProposal){kriaBefore={media:media.map(m=>({...m})),order:[...order],cover,current};const p=kriaProposal;if(p.type==='text')media[p.target].text=p.text;else if(p.type==='cover')cover=p.target;else order=[p.target,...order.filter(id=>id!==p.target)];kriaProposal=null;kriaApplied=true;direction='A';go('review');say('Change applied. '+(p.type==='cover'?'Cover updated.':'Draft saved.')+' You can undo in Kria.')}break;case'aiundo':if(kriaBefore){media.splice(0,media.length,...kriaBefore.media);order=[...kriaBefore.order];cover=kriaBefore.cover;current=kriaBefore.current;kriaBefore=null;kriaApplied=false;modal='';say('Kria’s last change undone.')}break;case'aidiscard':kriaProposal=null;kriaHelp='Your current post is unchanged. Tell me what you would like instead.';render();break;case'compose':if(chosen.size<(profile==='Instagram'?2:1)){say('Choose at least '+(profile==='Instagram'?2:1)+' moments for this post.');break}order=[...chosen];current=order[0];cover=current;go('composing');timer=setTimeout(()=>go('review'),1800);break;case'prepare':go('preparing');timer=setTimeout(()=>go('export'),1600);break;case'cover':cover=current;say('Cover updated. Draft saved.');break;case'savetext':media[current].text=textDraft;media[current].position=posDraft;go('review');say('Text saved. Prepare the post to update export files.');break;case'savestyle':media[current].look=look;go('review');say('Style selected in prototype. Export appearance needs validation.');break;case'savecaption':go('review');say('Caption saved.');break;case'copy':say('Prototype: caption copied. No clipboard change was made.');break;case'savephotos':say('Prototype: iOS would request permission to save the ordered slides.');break;case'simshare':case'simzip':modal='';say('Prototype only. No files have been shared.');break;case'sampleadd':modal='';say('Prototype: the native media picker opens here.');break;case'photodraft':profile='TikTok';order=order.filter(id=>!media[id].video);chosen=new Set(order);current=order[0];cover=current;go('review');say('Separate photo-only draft shown.');break;case'retryfailed':go('preparing');timer=setTimeout(()=>go('export'),1600);break;case'removefailed':order=order.filter(id=>id!==4);if(cover===4)cover=order[0];if(current===4)current=order[0];chosen.delete(4);go('review');say('Video removed. Review the draft before preparing.');break;case'play':say('Video poster in prototype. Playback would stay on this slide.');break;case'send':say('Prototype: Kria would propose a revised draft for review.');break;case'editor':direction='A';go('review');break;case'select':case'review':case'chat':case'arrange':case'text':case'style':case'caption':case'export':case'recovery':case'gallery':go(a);break;case'dismiss':modal='';render();break;default:modal=a;render()}});
document.addEventListener('submit',e=>{if(e.target.matches('.kria-composer')){e.preventDefault();proposeKria()}});
document.addEventListener('input',e=>{if(e.target.id==='kria-message'){kriaDraft=e.target.value;document.querySelector('.ai-send').disabled=!kriaDraft.trim();}if(e.target.id==='direction')note=e.target.value;if(e.target.id==='overlay-text'){textDraft=e.target.value;document.getElementById('text-count').textContent=textDraft.length;document.getElementById('edit-preview').innerHTML=canvas(current,true)}if(e.target.id==='post-caption'){caption=e.target.value;document.getElementById('caption-count').textContent=caption.length}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='kria-message'&&!e.shiftKey&&!e.isComposing){e.preventDefault();proposeKria();return}if(e.key==='Escape'&&modal){modal='';render()}if(e.key==='Tab'&&modal){const a=[...document.querySelectorAll('.sheet button:not([disabled]),.sheet textarea,.sheet input')],first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});if(screen==='text'){textDraft=media[current].text;posDraft=media[current].position||'center'}render();
